const VERSION = 'patatino-v1.0.0';
const CORE = ['./','./index.html','./manifest.webmanifest','./icon-32.png','./icon-180.png','./icon-192.png','./icon-512.png'];
self.addEventListener('install', e => e.waitUntil(caches.open(VERSION).then(c => c.addAll(CORE)).then(() => self.skipWaiting())));
self.addEventListener('activate', e => e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k)))).then(() => self.clients.claim())));
self.addEventListener('fetch', e => { const u = new URL(e.request.url); const asset = /font|icon|manifest/.test(u.pathname) || /fonts\.googleapis\.com|fonts\.gstatic\.com/.test(u.hostname); e.respondWith(asset ? caches.match(e.request).then(x => x || fetch(e.request).then(r => { const copy=r.clone(); caches.open(VERSION).then(c=>c.put(e.request,copy)); return r; })) : fetch(e.request).then(r => { const copy=r.clone(); caches.open(VERSION).then(c=>c.put(e.request,copy)); return r; }).catch(() => caches.match(e.request))); });
